// Validate Retry Request — Panoptes M11.5

const input = $input.first().json;

const incidentId = input.incident_id ?? null;
const executionId = input.execution_id ?? null;

const retryCount = Number(input.retry_count);
const maxRetries = Number(input.max_retries);

if (!incidentId) {
  throw new Error('Panoptes retry request missing incident_id');
}

if (!executionId) {
  throw new Error('Panoptes retry request missing execution_id');
}

if (!Number.isInteger(retryCount) || retryCount < 0) {
  throw new Error('Invalid retry_count');
}

if (!Number.isInteger(maxRetries) || maxRetries < 0) {
  throw new Error('Invalid max_retries');
}

return [{
  json: {
    incident_id: String(incidentId),
    execution_id: String(executionId),

    retry_count: retryCount,
    max_retries: maxRetries,

    retry_safety:
      String(input.retry_safety ?? 'UNKNOWN').toUpperCase(),

    side_effect_risk:
      String(input.side_effect_risk ?? 'UNKNOWN').toUpperCase(),

    approval_status:
      String(input.approval_status ?? 'NOT_REQUIRED').toUpperCase(),

    idempotency_guaranteed:
      input.idempotency_guaranteed === true
  }
}];

const response = $input.first().json;
const request = $('Validate Retry Request').first().json;

return [{
  json: {
    incident_id: request.incident_id,

    original_execution_id: request.execution_id,

    retry_execution_id:
      response.id ? String(response.id) : null,

    previous_retry_count: request.retry_count,
    new_retry_count: request.retry_count + 1,

    retry_requested: true,
    retry_result_received: Boolean(response.id),
  }
}];

// Check Retry Budget — Panoptes M11.4

const input = $input.first().json;

const retryCount = Number(input.retry_count);
const maxRetries = Number(input.max_retries);

if (!Number.isInteger(retryCount) || retryCount < 0) {
  throw new Error('Panoptes retry budget has invalid retry_count');
}

if (!Number.isInteger(maxRetries) || maxRetries < 0) {
  throw new Error('Panoptes retry budget has invalid max_retries');
}

const retryAllowed = retryCount < maxRetries;

return [{
  json: {
    ...input,

    retry_allowed: retryAllowed,
    retry_budget_exhausted: !retryAllowed,

    attempts_remaining: Math.max(
      maxRetries - retryCount,
      0
    )
  }
}];

// Return Retry Budget Exhausted — Panoptes M11.4

const input = $input.first().json;

return [{
  json: {
    incident_id: input.incident_id,
    original_execution_id: input.execution_id,

    retry_execution_id: null,

    previous_retry_count: input.retry_count,
    new_retry_count: input.retry_count,

    retry_requested: false,
    retry_result_received: false,

    retry_allowed: false,
    retry_budget_exhausted: true,

    reason:
      `Retry budget exhausted: ${input.retry_count}/${input.max_retries} attempts already used.`
  }
}];

// Check Retry Safety — Panoptes M11.5

const input = $input.first().json;

const retrySafety = input.retry_safety;
const sideEffectRisk = input.side_effect_risk;
const approvalStatus = input.approval_status;
const idempotent = input.idempotency_guaranteed === true;

let safetyAllowed = false;
let safetyReason = null;

// Explicit UNSAFE always fails closed.
if (retrySafety === 'UNSAFE') {
  safetyAllowed = false;
  safetyReason =
    'Retry is explicitly classified as UNSAFE.';
}

// Trusted idempotency guarantee permits repetition
// unless the operation was explicitly marked UNSAFE.
else if (idempotent) {
  safetyAllowed = true;
  safetyReason =
    'Retry permitted because the operation has a trusted idempotency guarantee.';
}

// Ordinary automatic retry.
else if (
  retrySafety === 'SAFE' &&
  sideEffectRisk === 'NONE'
) {
  safetyAllowed = true;
  safetyReason =
    'Retry is classified SAFE with no identified side-effect risk.';
}

// Conditional operation may proceed only after explicit human approval.
else if (
  retrySafety === 'CONDITIONAL' &&
  approvalStatus === 'APPROVED'
) {
  safetyAllowed = true;
  safetyReason =
    'Conditional retry explicitly authorized by a human operator.';
}

// Everything else fails closed.
else {
  safetyAllowed = false;
  safetyReason =
    `Retry blocked: safety=${retrySafety}, side_effect_risk=${sideEffectRisk}, approval_status=${approvalStatus}, idempotency_guaranteed=${idempotent}.`;
}

return [{
  json: {
    ...input,

    retry_safety_allowed: safetyAllowed,
    retry_safety_blocked: !safetyAllowed,
    safety_reason: safetyReason
  }
}];

// Return Retry Safety Blocked — Panoptes M11.5

const input = $input.first().json;

return [{
  json: {
    incident_id: input.incident_id,
    original_execution_id: input.execution_id,

    retry_execution_id: null,

    previous_retry_count: input.retry_count,
    new_retry_count: input.retry_count,

    retry_requested: false,
    retry_result_received: false,

    retry_allowed: false,
    retry_budget_exhausted: false,

    retry_safety_allowed: false,
    retry_safety_blocked: true,

    retry_safety: input.retry_safety,
    side_effect_risk: input.side_effect_risk,
    approval_status: input.approval_status,
    idempotency_guaranteed: input.idempotency_guaranteed,

    reason: input.safety_reason
  }
}];
